INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-1', 'wi-k8s-e1', 'p-001', 'Kicking off the control plane hardening initiative. We need 99.99% uptime on the API server. Let''s start with the HA design review.', FALSE, NOW() - INTERVAL '90 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-2', 'wi-k8s-e1', 'p-013', 'Are we capturing API call latencies during the failover? That data will be critical for our SLO model.', FALSE, NOW() - INTERVAL '88 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-3', 'wi-k8s-e1', 'p-001', 'Good point. I''ll add etcd latency histograms and leader election metrics to the telemetry plan.', FALSE, NOW() - INTERVAL '87 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-4', 'wi-k8s-e2', 'p-002', 'Starting the networking overhaul. Cilium will give us better observability and native XDP support.', FALSE, NOW() - INTERVAL '85 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-5', 'wi-k8s-e2', 'p-009', 'Will the Cilium migration require downtime? We need clear communication to the ops team.', FALSE, NOW() - INTERVAL '84 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-6', 'wi-k8s-e2', 'p-002', 'Zero-downtime via a rolling update strategy. I''ll document the phased rollout timeline.', FALSE, NOW() - INTERVAL '83 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-7', 'wi-k8s-f1', 'p-001', 'Let''s verify cross-AZ health checks are working before we move to feature-complete.', FALSE, NOW() - INTERVAL '75 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-8', 'wi-k8s-f1', 'p-004', 'Ran the failover simulation yesterday. cp1 → cp2 failover took 8 seconds. Well within our RTO budget.', FALSE, NOW() - INTERVAL '73 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-9', 'wi-k8s-f2', 'p-001', 'The S3 backup integration is in progress. We''re testing the snapshot scheduler with 6-hour intervals.', FALSE, NOW() - INTERVAL '70 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-10', 'wi-k8s-f2', 'p-013', 'Make sure we''re encrypting snapshots at rest and in transit. That''ll be a compliance requirement.', FALSE, NOW() - INTERVAL '68 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-11', 'wi-k8s-f2', 'p-001', 'Snapshot encryption is enabled via AWS KMS. Working on restore automation next.', FALSE, NOW() - INTERVAL '66 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-12', 'wi-k8s-f3', 'p-002', 'Cilium DaemonSet deployment kicked off. All nodes reporting ready. eBPF mode is active on 18/20 nodes.', FALSE, NOW() - INTERVAL '60 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-13', 'wi-k8s-f3', 'p-004', 'The 2 nodes failing eBPF check — are those the ARM64 workers? Need to verify kernel version compatibility.', FALSE, NOW() - INTERVAL '58 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-14', 'wi-k8s-f3', 'p-002', 'Correct. Running kernel 5.8 on the ARM nodes. eBPF requires 5.10+. Upgrading as part of the next maintenance window.', FALSE, NOW() - INTERVAL '57 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-15', 'wi-k8s-f4', 'p-004', 'Storage classes deployed and tested. EBS gp3 provisioning is fast — sub-2s mount time. NFS is stable on 5 test StatefulSets.', FALSE, NOW() - INTERVAL '65 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-16', 'wi-k8s-f4', 'p-001', 'Solid. Let''s make sure the storage classes are the default for new claims.', FALSE, NOW() - INTERVAL '64 days') ON CONFLICT (id) DO NOTHING;
